/bin/bash -c "node - <<'NODE'
const { spawnSync } = require('node:child_process');
const cases = [
  ['--a', 'http://example.com/x?y=1#z', '--b', 'other.com'],
  ['--a', 'example.com/p?q=1#f', '--b', 'other.com'],
  ['--a', '/path', '--b', 'other.com'],
  ['--a', '/path', '--b', ''],
  ['--a', 'http://user:pass@example.com:8080/p?q=1#f', '--b', 'other.com'],
  ['--a', 'HTTP:Example.com/P', '--b', ''],
  ['--a', 'http://example.com/a b?x=1 2#f g', '--b', 'other.com'],
  ['--a', 'http://example.com/%2F?x=%2B', '--b', 'other.com'],
  ['--a', '//example.com/p?q=1#f', '--b', 'other.com'],
  ['--a', 'foo:bar', '--b', 'baz'],
  ['--a', 'foo:bar', '--b', ''],
  ['--a', ' http://example.com/path ', '--b', 'repl.example'],
  ['--a', '?x=1#f', '--b', 'other.com'],
  ['--a', '?x=1#f', '--b', ''],
  ['--a', 'http://///weird', '--b', 'other.com'],
  ['--a', 'ümlaut', '--b', 'TÄST.DE'],
];
let failed = false;
for (const args of cases) {
  const py = spawnSync('/workspace/dataset/test2_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test2.mjs', ...args], { encoding: 'utf8' });
  const pyOut = py.stdout + py.stderr;
  const jsOut = js.stdout + js.stderr;
  const ok = py.status === js.status && pyOut === jsOut;
  if ("'!ok) {
    failed = true;
    console.log('"'MISMATCH');
    console.log(JSON.stringify(args));
    console.log('PY STATUS', py.status);
    console.log(pyOut);
    console.log('JS STATUS', js.status);
    console.log(jsOut);
  }
}
if ("'!failed) {
  console.log('"'all_success_cases_match');
}
NODE"

