/bin/bash -c "node - <<'NODE'
const { spawnSync } = require('node:child_process');
const cases = [
  [],
  ['--a', 'x'],
  ['--a', 'x', '--c', 'z', '--b', 'y'],
  ['--a', 'x', '--b', '-foo.com'],
  ['--a', 'http://example.com/p', '--b', 'other.com:9090'],
  ['--a', 'http://example.com/p', '--b', 'xn--abc.com'],
];
function normalize(text) {
  return text
    .replace(/test2_executable/g, 'PROGRAM')
    .replace(/test2\\.mjs/g, 'PROGRAM')
    .replace(/\\[PYI-\\d+:ERROR\\]/g, '[PYI-PID:ERROR]');
}
let failed = false;
for (const args of cases) {
  const py = spawnSync('/workspace/dataset/test2_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test2.mjs', ...args], { encoding: 'utf8' });
  const pyOut = normalize(py.stdout + py.stderr);
  const jsOut = normalize(js.stdout + js.stderr);
  const ok = py.status === js.status && pyOut === jsOut;
  if ("'!ok) {
    failed = true;
    console.log('"'MISMATCH');
    console.log(JSON.stringify(args));
    console.log('PY STATUS', py.status);
    console.log(pyOut);
    console.log('JS STATUS', js.status);
    console.log(jsOut);
  }
}
if ("'!failed) {
  console.log('"'all_error_cases_match_after_normalization');
}
NODE"

